tasks.check:
set -o pipefail
cd /home/bcorfman/dev/freytag-forge
export PYTHONPATH=$PWD TMPDIR=/tmp
PY=.venv/bin/python
for f in scripts/ringer/phase2/act3c_probe.py scripts/ringer/phase2/check_act3c_probe.py tests/test_act3c_probe.py; do [ -s $f ] || { echo "WHY: $f missing"; exit 1; }; done
$PY -m ruff format --check scripts/ringer/phase2 tests/test_act3c_probe.py || { echo "WHY: not ruff-formatted"; exit 1; }
$PY -m ruff check scripts/ringer/phase2 tests/test_act3c_probe.py || { echo "WHY: ruff check failed"; exit 1; }
for p in none clean costly stall; do O=$(mktemp -d); $PY scripts/ringer/phase2/act3c_probe.py --prefix $p --n 1 --out $O --dry-run || { echo "WHY: dry run failed for $p"; exit 1; }; $PY scripts/ringer/phase2/check_act3c_probe.py $O 1 --mode dry || { echo "WHY: artifact check failed for $p"; exit 1; }; done
$PY -m pytest -q -p no:cacheprovider tests/test_act3c_probe.py || { echo "WHY: probe tests failed"; exit 1; }
echo ok
